    debug_csr_save_oA = 1'b0;
    debug_cause_oA = DBG_CAUSE_EBREAK;
    debug_mode_dA = debug_mode_qVotedA;
    nmi_mode_dA = nmi_mode_qVotedA;
    perf_tbranch_oA = 1'b0;
    perf_jump_oA = 1'b0;
    controller_run_oA = 1'b0;
    unique case (ctrl_fsm_csVotedA)
