        end
      WAIT_SLEEP : 
        begin
          ctrl_busy_oA = 1'b0;
          instr_req_oA = 1'b0;
          halt_ifA = 1'b1;
          flush_idA = 1'b1;
          ctrl_fsm_nsA = SLEEP;
        end
      SLEEP : 
        begin
