          halt_ifA = 1'b1;
          flush_idA = 1'b1;
          if (irq_nm_iA||irq_pending_iA||debug_req_iA||debug_mode_qVotedA||debug_single_step_iA)
            begin
              ctrl_fsm_nsA = FIRST_FETCH;
            end
          else
            begin
              ctrl_busy_oA = 1'b0;
            end
        end
      FIRST_FETCH : 
        begin
          if (id_in_ready_oA)
            begin
              ctrl_fsm_nsA = DECODE;
            end

          if (handle_irqA)
            begin
              ctrl_fsm_nsA = IRQ_TAKEN;
              halt_ifA = 1'b1;
            end

          if (enter_debug_modeA)
            begin
              ctrl_fsm_nsA = DBG_TAKEN_IF;
              halt_ifA = 1'b1;
            end

        end
      DECODE : 
        begin
          controller_run_oA = 1'b1;
