                    csr_mtval_oA = instr_fetch_err_plus2_iA ? (pc_id_iA+32'd2) : pc_id_iA;
                  end
                illegal_insn_prioA : 
                  begin
                    exc_cause_oA = EXC_CAUSE_ILLEGAL_INSN;
                    csr_mtval_oA = instr_is_compressed_iA ? {16'b0, instr_compressed_iA} : instr_iA;
                  end
                ecall_insn_prioA : 
                  begin
                    exc_cause_oA = (priv_mode_iA==PRIV_LVL_M) ? EXC_CAUSE_ECALL_MMODE : EXC_CAUSE_ECALL_UMODE;
                  end
                ebrk_insn_prioA : 
                  begin
