                  pc_mux_oB = PC_ERET;
                  pc_set_oB = 1'b1;
                  csr_restore_mret_id_oB = 1'b1;
                  if (nmi_mode_qVotedB)
                    begin
                      nmi_mode_dB = 1'b0;
                    end

                end
              else
                if (dret_insnB)
                  begin
                    pc_mux_oB = PC_DRET;
                    pc_set_oB = 1'b1;
                    debug_mode_dB = 1'b0;
                    csr_restore_dret_id_oB = 1'b1;
                  end
                else
                  if (wfi_insnB)
                    begin
                      ctrl_fsm_nsB = WAIT_SLEEP;
                    end

            end
          if (enter_debug_mode_prio_qVotedB&&!(ebrk_insn_prioB&&ebreak_into_debugB))
            begin
              ctrl_fsm_nsB = DBG_TAKEN_IF;
            end

        end
      default : 
        begin
          instr_req_oB = 1'b0;
          ctrl_fsm_nsB = RESET;
        end
    endcase
  end

always_comb
  begin
    instr_req_oC = 1'b1;
    csr_save_if_oC = 1'b0;
    csr_save_id_oC = 1'b0;
    csr_restore_mret_id_oC = 1'b0;
    csr_restore_dret_id_oC = 1'b0;
    csr_save_cause_oC = 1'b0;
    csr_mtval_oC = '0;
    pc_mux_oC = PC_BOOT;
    pc_set_oC = 1'b0;
    exc_pc_mux_oC = EXC_PC_IRQ;
    exc_cause_oC = EXC_CAUSE_INSN_ADDR_MISA;
    ctrl_fsm_nsC = ctrl_fsm_csVotedC;
    ctrl_busy_oC = 1'b1;
    halt_ifC = 1'b0;
    retain_idC = 1'b0;
    flush_idC = 1'b0;
    debug_csr_save_oC = 1'b0;
    debug_cause_oC = DBG_CAUSE_EBREAK;
    debug_mode_dC = debug_mode_qVotedC;
    nmi_mode_dC = nmi_mode_qVotedC;
    perf_tbranch_oC = 1'b0;
    perf_jump_oC = 1'b0;
    controller_run_oC = 1'b0;
    unique case (ctrl_fsm_csVotedC)
      RESET : 
        begin
          instr_req_oC = 1'b0;
          pc_mux_oC = PC_BOOT;
          pc_set_oC = 1'b1;
          if (fetch_enable_iC==1'b1)
            begin
              ctrl_fsm_nsC = BOOT_SET;
            end

        end
      BOOT_SET : 
        begin
          instr_req_oC = 1'b1;
          pc_mux_oC = PC_BOOT;
          pc_set_oC = 1'b1;
          ctrl_fsm_nsC = FIRST_FETCH;
        end
      WAIT_SLEEP : 
        begin
          ctrl_busy_oC = 1'b0;
          instr_req_oC = 1'b0;
          halt_ifC = 1'b1;
          flush_idC = 1'b1;
          ctrl_fsm_nsC = SLEEP;
        end
      SLEEP : 
        begin
          instr_req_oC = 1'b0;
          halt_ifC = 1'b1;
          flush_idC = 1'b1;
          if (irq_nm_iC||irq_pending_iC||debug_req_iC||debug_mode_qVotedC||debug_single_step_iC)
            begin
              ctrl_fsm_nsC = FIRST_FETCH;
            end
          else
            begin
              ctrl_busy_oC = 1'b0;
            end
        end
      FIRST_FETCH : 
        begin
          if (id_in_ready_oC)
            begin
              ctrl_fsm_nsC = DECODE;
            end

          if (handle_irqC)
            begin
              ctrl_fsm_nsC = IRQ_TAKEN;
              halt_ifC = 1'b1;
            end

          if (enter_debug_modeC)
            begin
              ctrl_fsm_nsC = DBG_TAKEN_IF;
              halt_ifC = 1'b1;
            end

        end
      DECODE : 
        begin
          controller_run_oC = 1'b1;
          pc_mux_oC = PC_JUMP;
          if (special_reqC)
            begin
              retain_idC = 1'b1;
              ctrl_fsm_nsC = FLUSH;
            end

          if (branch_set_iC||jump_set_iC)
            begin
              pc_set_oC = 1'b1;
              perf_tbranch_oC = branch_set_iC;
              perf_jump_oC = jump_set_iC;
            end

          if ((enter_debug_modeC||handle_irqC)&&(stallC||instr_valid_iC))
            begin
              halt_ifC = 1'b1;
            end

          if (!stallC&&!special_reqC&&!instr_valid_iC)
            begin
              if (enter_debug_modeC)
                begin
                  ctrl_fsm_nsC = DBG_TAKEN_IF;
                  halt_ifC = 1'b1;
                end
              else
                if (handle_irqC)
                  begin
                    ctrl_fsm_nsC = IRQ_TAKEN;
                    halt_ifC = 1'b1;
                  end

            end

        end
      IRQ_TAKEN : 
        begin
          pc_mux_oC = PC_EXC;
          exc_pc_mux_oC = EXC_PC_IRQ;
          if (handle_irqC)
            begin
              pc_set_oC = 1'b1;
              csr_save_if_oC = 1'b1;
              csr_save_cause_oC = 1'b1;
              if (irq_nm_iC&&!nmi_mode_qVotedC)
                begin
                  exc_cause_oC = EXC_CAUSE_IRQ_NM;
                  nmi_mode_dC = 1'b1;
                end
              else
                if (irqs_iC.irq_fast!=16'b0)
                  begin
                    exc_cause_oC = exc_cause_e' ({3'b101, mfip_idC}) ;
                  end
                else
                  if (irqs_iC.irq_external)
                    begin
                      exc_cause_oC = EXC_CAUSE_IRQ_EXTERNAL_M;
                    end
                  else
                    if (irqs_iC.irq_software)
                      begin
                        exc_cause_oC = EXC_CAUSE_IRQ_SOFTWARE_M;
                      end
                    else
                      begin
                        exc_cause_oC = EXC_CAUSE_IRQ_TIMER_M;
                      end
            end

          ctrl_fsm_nsC = DECODE;
        end
      DBG_TAKEN_IF : 
        begin
          pc_mux_oC = PC_EXC;
          exc_pc_mux_oC = EXC_PC_DBD;
          flush_idC = 1'b1;
          pc_set_oC = 1'b1;
          csr_save_if_oC = 1'b1;
          debug_csr_save_oC = 1'b1;
          csr_save_cause_oC = 1'b1;
          if (trigger_match_iC)
            begin
              debug_cause_oC = DBG_CAUSE_TRIGGER;
            end
          else
            if (debug_req_iC)
              begin
                debug_cause_oC = DBG_CAUSE_HALTREQ;
              end
            else
              begin
                debug_cause_oC = DBG_CAUSE_STEP;
              end
          debug_mode_dC = 1'b1;
          ctrl_fsm_nsC = DECODE;
        end
      DBG_TAKEN_ID : 
        begin
          flush_idC = 1'b1;
          pc_mux_oC = PC_EXC;
          pc_set_oC = 1'b1;
          exc_pc_mux_oC = EXC_PC_DBD;
          if (ebreak_into_debugC&&!debug_mode_qVotedC)
            begin
              csr_save_cause_oC = 1'b1;
              csr_save_id_oC = 1'b1;
              debug_csr_save_oC = 1'b1;
              debug_cause_oC = DBG_CAUSE_EBREAK;
            end

          debug_mode_dC = 1'b1;
          ctrl_fsm_nsC = DECODE;
        end
      FLUSH : 
        begin
          halt_ifC = 1'b1;
          flush_idC = 1'b1;
          ctrl_fsm_nsC = DECODE;
          if (exc_req_qVotedC||store_err_qVotedC||load_err_qVotedC)
            begin
              pc_set_oC = 1'b1;
              pc_mux_oC = PC_EXC;
              exc_pc_mux_oC = debug_mode_qVotedC ? EXC_PC_DBG_EXC : EXC_PC_EXC;
              begin : g_no_writeback_mepc_saveC
                csr_save_id_oC = 1'b0;
              end
              csr_save_cause_oC = 1'b1;
              unique case (1'b1)
                instr_fetch_err_prioC : 
                  begin
                    exc_cause_oC = EXC_CAUSE_INSTR_ACCESS_FAULT;
                    csr_mtval_oC = instr_fetch_err_plus2_iC ? (pc_id_iC+32'd2) : pc_id_iC;
                  end
                illegal_insn_prioC : 
                  begin
                    exc_cause_oC = EXC_CAUSE_ILLEGAL_INSN;
                    csr_mtval_oC = instr_is_compressed_iC ? {16'b0, instr_compressed_iC} : instr_iC;
                  end
                ecall_insn_prioC : 
                  begin
                    exc_cause_oC = (priv_mode_iC==PRIV_LVL_M) ? EXC_CAUSE_ECALL_MMODE : EXC_CAUSE_ECALL_UMODE;
                  end
                ebrk_insn_prioC : 
                  begin
                    if (debug_mode_qVotedC|ebreak_into_debugC)
                      begin
                        pc_set_oC = 1'b0;
                        csr_save_id_oC = 1'b0;
                        csr_save_cause_oC = 1'b0;
                        ctrl_fsm_nsC = DBG_TAKEN_ID;
                        flush_idC = 1'b0;
                      end
                    else
                      begin
                        exc_cause_oC = EXC_CAUSE_BREAKPOINT;
                      end
                  end
                store_err_prioC : 
                  begin
                    exc_cause_oC = EXC_CAUSE_STORE_ACCESS_FAULT;
                    csr_mtval_oC = lsu_addr_last_iC;
                  end
                load_err_prioC : 
                  begin
                    exc_cause_oC = EXC_CAUSE_LOAD_ACCESS_FAULT;
                    csr_mtval_oC = lsu_addr_last_iC;
                  end
                default : ;
              endcase
            end
          else
            begin
              if (mret_insnC)
                begin
                  pc_mux_oC = PC_ERET;
                  pc_set_oC = 1'b1;
                  csr_restore_mret_id_oC = 1'b1;
                  if (nmi_mode_qVotedC)
                    begin
                      nmi_mode_dC = 1'b0;
                    end

                end
              else
                if (dret_insnC)
                  begin
                    pc_mux_oC = PC_DRET;
                    pc_set_oC = 1'b1;
                    debug_mode_dC = 1'b0;
                    csr_restore_dret_id_oC = 1'b1;
                  end
                else
                  if (wfi_insnC)
                    begin
                      ctrl_fsm_nsC = WAIT_SLEEP;
                    end

            end
          if (enter_debug_mode_prio_qVotedC&&!(ebrk_insn_prioC&&ebreak_into_debugC))
            begin
              ctrl_fsm_nsC = DBG_TAKEN_IF;
            end

        end
      default : 
        begin
          instr_req_oC = 1'b0;
          ctrl_fsm_nsC = RESET;
        end
    endcase
  end
assign flush_id_oA = flush_idA;
assign flush_id_oB = flush_idB;
assign flush_id_oC = flush_idC;
assign debug_mode_oA = debug_mode_qVotedA;
assign debug_mode_oB = debug_mode_qVotedB;
assign debug_mode_oC = debug_mode_qVotedC;
assign nmi_mode_oA = nmi_mode_qVotedA;
assign nmi_mode_oB = nmi_mode_qVotedB;
assign nmi_mode_oC = nmi_mode_qVotedC;
assign stallA = stall_id_iA;
assign stallB = stall_id_iB;
assign stallC = stall_id_iC;
assign id_in_ready_oA = ~stallA&~halt_ifA&~retain_idA;
assign id_in_ready_oB = ~stallB&~halt_ifB&~retain_idB;
assign id_in_ready_oC = ~stallC&~halt_ifC&~retain_idC;
assign instr_valid_clear_oA = ~ (stallA|retain_idA) |flush_idA;
assign instr_valid_clear_oB = ~ (stallB|retain_idB) |flush_idB;
assign instr_valid_clear_oC = ~ (stallC|retain_idC) |flush_idC;

always_ff @( posedge clk_iA or negedge rst_niA )
